static Dictionary<string, int> Validar(string json)
{
    Snapshot? copia = JsonSerializer.Deserialize<Snapshot>(json);
    if (copia is null || copia.Versao != 1 || copia.Itens is null) throw new InvalidOperationException("snapshot inválido");
    var candidato = new Dictionary<string, int>(StringComparer.Ordinal);
    foreach (Item? item in copia.Itens)
    {
        if (item is null || string.IsNullOrWhiteSpace(item.Id) || item.Quantidade < 0 || !candidato.TryAdd(item.Id, item.Quantidade))
            throw new InvalidOperationException("item inválido ou repetido");
    }
    return candidato;
}
