sealed class Estoque
{
    private readonly object guarda = new();
    private int saldo;
    public Estoque(int inicial)
    {
        if (inicial < 0) throw new ArgumentOutOfRangeException(nameof(inicial));
        saldo = inicial;
    }
    public int Saldo { get { lock (guarda) return saldo; } }
    public bool TentarBaixar(int quantidade)
    {
        if (quantidade <= 0) throw new ArgumentOutOfRangeException(nameof(quantidade));
        lock (guarda)
        {
            if (quantidade > saldo) return false;
            saldo -= quantidade;
            return true;
        }
    }
}

using System;
