using System.Threading.Channels;
using System.Threading.Tasks;
using var origem = new CancellationTokenSource();
var canal = Channel.CreateBounded<int>(new BoundedChannelOptions(2)
{
    FullMode = BoundedChannelFullMode.Wait, SingleWriter = true, SingleReader = true
});
async Task ProduzirAsync()
{
    Exception? falha = null;
    try { for (int i = 1; i <= 4; i++) await canal.Writer.WriteAsync(i, origem.Token); }
    catch (Exception erro) { falha = erro; origem.Cancel(); throw; }
    finally { canal.Writer.TryComplete(falha); }
}
async Task<int> ConsumirAsync()
{
    try
    {
        int total = 0;
        await foreach (int item in canal.Reader.ReadAllAsync(origem.Token)) total += item;
        return total;
    }
    catch { origem.Cancel(); throw; }
}
Task produtor = ProduzirAsync();
Task<int> consumidor = ConsumirAsync();
await Task.WhenAll(produtor, consumidor);
