using System;
using System.Collections.Generic;
var oficina = new Oficina();
Resultado primeira = oficina.Confirmar("pedido-1", "OS-1");
Resultado repetida = oficina.Confirmar("pedido-1", "OS-1");
_ = oficina.Confirmar("pedido-2", "OS-1");
Console.WriteLine(primeira.Saldo);
Console.WriteLine(oficina.Saldo);
Console.WriteLine(primeira == repetida);
sealed record Ordem(string Id, string Status, int Quantidade);
sealed record Resultado(string Id, string Status, int Saldo);
sealed class Oficina
{
    private readonly object guarda = new();
    private int saldo = 5;
    private readonly Dictionary<string, Ordem> ordens = new(StringComparer.Ordinal)
    { ["OS-1"] = new Ordem("OS-1", "aberta", 2) };
    private readonly Dictionary<string, Resultado> pedidos = new(StringComparer.Ordinal);
    public int Saldo { get { lock (guarda) return saldo; } }
    public Resultado Confirmar(string chave, string id)
    {
        if (string.IsNullOrWhiteSpace(chave) || string.IsNullOrWhiteSpace(id)) throw new ArgumentException("chave e ID obrigatórios");
        lock (guarda)
        {
            if (pedidos.TryGetValue(chave, out Resultado? anterior))
            {
                if (anterior.Id != id) throw new InvalidOperationException("chave reutilizada");
                return anterior;
            }
            if (!ordens.TryGetValue(id, out Ordem? ordem)) throw new InvalidOperationException("ordem ausente");
            if (ordem.Status == "aberta")
            {
                if (ordem.Quantidade > saldo) throw new InvalidOperationException("estoque insuficiente");
                saldo -= ordem.Quantidade;
                ordem = ordem with { Status = "confirmada" };
                ordens[id] = ordem;
            }
            var resposta = new Resultado(id, ordem.Status, saldo);
            pedidos.Add(chave, resposta);
            return resposta;
        }
    }
}

