        if (atual.Status == "confirmada") return atual;
        if (atual.Status != "aberta" || atual.Quantidade <= 0 || atual.Quantidade > atual.Saldo)
            throw new InvalidOperationException("confirmação inválida");
        return atual with { Status = "confirmada", Saldo = atual.Saldo - atual.Quantidade };
    }
    estado = Confirmar(estado, id);
    estado = Confirmar(estado, id);
    if (estado.Saldo != 3) throw new Exception("baixa repetida");
    string caminho = Path.Combine(pasta, "snapshot.json");
    File.WriteAllText(caminho, JsonSerializer.Serialize(new Snapshot(1, estado)));
    Snapshot? copia = JsonSerializer.Deserialize<Snapshot>(File.ReadAllText(caminho));
    if (copia is null || copia.Versao != 1 || copia.Dados is null
        || copia.Dados.Id != "OS-1" || copia.Dados.Status != "confirmada"
        || copia.Dados.Quantidade != 2 || copia.Dados.Saldo != 3)
        throw new InvalidOperationException("snapshot rejeitado");
    Console.WriteLine($"{copia.Dados.Id}:{copia.Dados.Status}:{copia.Dados.Saldo}");
    Console.WriteLine("repetição e restauração verificadas");
}
